{% for customer in customers %}

    {{ customer.name }}
    {{ customer.default_receivable_account or 'Desconhecido' }}
    {{ customer.tax_id or '999999990' }}
    {{ customer.customer_name }}

        {{ ((customer.address_line1 or '') ~ (' ' ~ customer.address_line2 if customer.address_line2 else '')) or 'Desconhecido' }}
        {{ customer.city or 'Desconhecido' }}
        {{ customer.pincode or 'Desconhecido' }}
        {{ customer.country_code }}

    {{ 1 if customer.at_is_self_billing else 0 }}

{% endfor %}

{% for supplier in suppliers %}

    {{ supplier.name }}
    {{ supplier.default_payable_account or 'Desconhecido' }}
    {{ supplier.tax_id or '999999990' }}
    {{ supplier.supplier_name }}

        {{ ((supplier.address_line1 or '') ~ (' ' ~ supplier.address_line2 if supplier.address_line2 else '')) or 'Desconhecido' }}
        {{ supplier.city or 'Desconhecido' }}
        {{ supplier.pincode or 'Desconhecido' }}
        {{ supplier.country_code }}

    0

{% endfor %}

{% for item in products %}

    {{ 'P' if item.is_stock_item else 'S' }}
    {{ item.item_code }}
    {{ item.item_name or item.item_code }}
    {{ item.item_code }}

{% endfor %}


    {% for tax in tax_table %}

        IVA
        {{ tax.region }}
        {{ tax.tax_code }}
        {{ tax.description or tax.tax_code }}
        {{ '%.2f'|format(tax.rate or 0) }}

    {% endfor %}
